<?php
declare(strict_types=1);
require_once __DIR__.'/../plugins/generic/estrabao/LegacyDocSource.inc.php';
function withLegacyReview(callable $callback):void {
 withDeskPanel(function($service,$request,$form,$publication,$old,$dir)use($callback){
  $path=$old.'.doc';copy(__DIR__.'/fixtures/legacy/synthetic.doc',$path);Services::$files[0]->data['path']=basename($path);
  $request->vars['fingerprint']=(new EstrabaoAdmissionBridge())->analyze($form)['fingerprint'];
  try{$callback($service,$request,$form,$publication,$path,$dir);}finally{unlink($path);}
 });
}
function legacyWordOffset(string $bytes):int {
 $pos=strpos($bytes,"W\0o\0r\0d\0D\0o\0c\0u\0m\0e\0n\0t\0");return (unpack('V',substr($bytes,$pos+116,4))[1]+1)*512;
}
test('DOC identificado é somente fonte de revisão humana sem texto ou APA automática',function(){withLegacyReview(function($s,$r,$f,$pub,$path){$a=(new EstrabaoAdmissionBridge())->analyze($f,true);same('manual_review_required',$a['decision']);same(true,$a['reviewable']);same('doc_manual_v1',$a['review_mode']);same(false,$a['document']['available']);same([],$a['document']['paragraphs']);same(hash_file('sha256',$path),$a['binding']['document_sha256']);same([],$a['corrections']);same(false,$s->view($r,17)['release_active']);});});
test('DOC só libera com abertura declarada e revisão APA explícitas registradas',function(){withLegacyReview(function($s,$r,$f,$pub,$path,$dir){reviewPost($s,$r);reviewRejects(function()use($s,$r){$s->save($r,17);});$r->vars['docOpened']='1';$s->save($r,17);$v=$s->view($r,17);same(true,$v['release_active']);same('doc_manual_v1',$v['events'][0]['review_mode']);same(77,$v['events'][0]['reviewer_id']);same(0600,fileperms($dir.'/review-3-17.json')&0777);same(false,strpos(file_get_contents($dir.'/review-3-17.json'),'Synthetic paragraph')!==false);});});
test('DOC liberado preserva validações nativas e revogação continua possível',function(){withLegacyReview(function($s,$r,$f){reviewPost($s,$r);$r->vars['docOpened']='1';$s->save($r,17);$p=new EstrabaoPlugin();$p->enabled=true;$value=false;$f->errors=['csrf'=>'native'];$p->validateAdmission('submissionsubmitstep4form::validate',[$f,&$value]);same(false,$value);same(['csrf'=>'native'],$f->errors);reviewPost($s,$r,'revoke');$s->save($r,17);same(false,$s->view($r,17)['release_active']);same('doc_manual_v1',$s->view($r,17)['events'][1]['review_mode']);});});
test('DOC sem revisão permanece pendente com explicação de formato aceito',function(){withLegacyReview(function($s,$r,$f){$p=new EstrabaoPlugin();$p->enabled=true;$value=null;$p->validateAdmission('submissionsubmitstep4form::validate',[$f,&$value]);same(false,$value);same('plugins.generic.estrabao.docAuthorPending',$f->errors['estrabaoAdmission']);});});
test('download DOC usa arquivo servidor e extensão correta sem inline',function(){withLegacyReview(function($s,$r){Services::$downloads=[];$s->download($r,17);same([[111,'manuscrito.doc',false]],Services::$downloads);});});
test('minuta DOC mantém manuscrito inconclusivo e permite checklist separado',function(){withLegacyReview(function($s,$r){$d=$s->draft($r,17);same(false,$d['draft']['send_authorized']);same(true,count($d['pending_groups'])>0);$v=(new EstrabaoEditorialReviewService())->view($r,17,$d);same(12,count($v['items']));same(false,$s->view($r,17)['release_active']);});});
foreach(['opened','apa','csrf','post','author','other_context','complete','fingerprint','revision']as$case){test('DOC manual recusa requisição inválida '.$case,function()use($case){withLegacyReview(function($s,$r,$f)use($case){reviewPost($s,$r);$r->vars['docOpened']='1';if($case==='opened'){$r->vars['docOpened']=true;}elseif($case==='apa'){unset($r->vars['apaReviewed']);}elseif($case==='csrf'){$r->csrf=false;}elseif($case==='post'){$r->post=false;}elseif($case==='author'){DAORegistry::$roles=[];}elseif($case==='other_context'){$f->submission->data['contextId']=8;}elseif($case==='complete'){$f->submission->data['submissionProgress']=0;}elseif($case==='fingerprint'){$r->vars['fingerprint']=str_repeat('0',64);}else{$r->vars['revision']='1';}reviewRejects(function()use($s,$r){$s->save($r,17);});});});}
foreach(['bytes','file_id','submission_file_id','language','ambiguous','unreadable']as$case){test('mudança invalida DOC liberado '.$case,function()use($case){withLegacyReview(function($s,$r,$f,$pub,$path)use($case){reviewPost($s,$r);$r->vars['docOpened']='1';$s->save($r,17);if($case==='bytes'){$b=file_get_contents($path);$b[strlen($b)-1]=chr(ord($b[strlen($b)-1])^1);file_put_contents($path,$b);}elseif($case==='file_id'){Services::$files[0]->data['fileId']=222;}elseif($case==='submission_file_id'){Services::$files[0]->data['id']=22;}elseif($case==='language'){$f->submission->data['locale']='en_US';}elseif($case==='ambiguous'){Services::$files[]=clone Services::$files[0];}else{file_put_contents($path,'bad');}same(false,$s->view($r,17)['release_active']);});});}
test('declaração de DOC não permite contornar ABNT comprovada em DOCX',function(){withReview(function($s,$r){reviewPost($s,$r);$r->vars['docOpened']='1';$r->vars['review_mode']='doc_manual_v1';reviewRejects(function()use($s,$r){$s->save($r,17);});same(false,$s->view($r,17)['release_active']);},true);});
test('histórico DOC exige marcador servidor e não pode usar aprovação de modo antigo',function(){withLegacyReview(function($s,$r,$f,$pub,$path,$dir){reviewPost($s,$r);$r->vars['docOpened']='1';$s->save($r,17);$p=$dir.'/review-3-17.json';$l=json_decode(file_get_contents($p),true);unset($l['events'][0]['review_mode']);file_put_contents($p,json_encode($l));same(false,$s->view($r,17)['release_active']);});});
test('DOC não é alternativa automática para DOCX rejeitado e renomeado',function(){withLegacyReview(function($s,$r,$f,$pub,$path){file_put_contents($path,'PK'.str_repeat('x',8000));$a=(new EstrabaoAdmissionBridge())->analyze($f);same(null,$a['fingerprint']);same(false,$a['reviewable']);same('manual_review_required',$a['decision']);});});
foreach(['truncated','magic','version','byte_order','sector_shift','difat','fat_count','fat_outside','directory_cycle','encrypted','obfuscated','fib','word_name','macro','table_name','word_size','oversize','rtf']as$case){test('identificação conservadora de DOC retém '.$case,function()use($case){withLegacyReview(function($s,$r,$f,$pub,$path)use($case){$b=file_get_contents($path);$word=legacyWordOffset($b);$name=strpos($b,"W\0o\0r\0d\0D\0o\0c\0u\0m\0e\0n\0t\0");
 if($case==='truncated'){$b=substr($b,0,511);}elseif($case==='magic'){$b[0]='X';}elseif($case==='version'){$b=substr_replace($b,pack('v',4),26,2);}elseif($case==='byte_order'){$b=substr_replace($b,pack('v',0),28,2);}elseif($case==='sector_shift'){$b=substr_replace($b,pack('v',12),30,2);}elseif($case==='difat'){$b=substr_replace($b,pack('V',1),72,4);}elseif($case==='fat_count'){$b=substr_replace($b,pack('V',110),44,4);}elseif($case==='fat_outside'){$b=substr_replace($b,pack('V',999999),76,4);}elseif($case==='directory_cycle'){$directory=unpack('V',substr($b,48,4))[1];$fat=unpack('V',substr($b,76,4))[1];$b=substr_replace($b,pack('V',$directory),($fat+1)*512+$directory*4,4);}elseif(in_array($case,['encrypted','obfuscated'],true)){$flags=unpack('v',substr($b,$word+10,2))[1];$b=substr_replace($b,pack('v',$flags|($case==='encrypted'?0x100:0x8000)),$word+10,2);}elseif($case==='fib'){$b=substr_replace($b,pack('v',0),$word,2);}elseif($case==='word_name'){$b[$name]='X';}elseif($case==='macro'){$b=substr_replace($b,"V\0B\0A\0\0\0",$name,8);$b=substr_replace($b,pack('v',8),$name+64,2);}elseif($case==='table_name'){$p=strpos($b,"1\0T\0a\0b\0l\0e\0");$b[$p]='X';}elseif($case==='word_size'){$b=substr_replace($b,pack('V',100),$name+120,4);}elseif($case==='oversize'){$b=str_repeat('x',EstrabaoLegacyDocSource::MAX_FILE+1);}else{$b='{\\rtf1 synthetic}';}
 file_put_contents($path,$b);$a=(new EstrabaoAdmissionBridge())->analyze($f);same(null,$a['fingerprint']);same(false,$a['reviewable']);same('manual_review_required',$a['decision']);
 });});}
test('ledger APA vazio não reinicia histórico nem libera DOC',function(){withLegacyReview(function($s,$r,$f,$pub,$path,$dir){$p=$dir.'/review-3-17.json';file_put_contents($p,'');chmod($p,0600);reviewRejects(function()use($s,$r){$s->view($r,17);});same('',file_get_contents($p));});});
